#!/usr/bin/env node
/**
 * Rewrites every `<img src="/assets/images/NAME.jpg" ...>` in the page HTML
 * (and src/partials) into a `<picture>` with a WebP `<source>` (srcset at the
 * widths generated by gen-responsive-images.mjs) plus the original JPEG as
 * the `<img>` fallback, itself carrying a matching srcset/sizes. The `<img>`
 * `src` stays the original full-size JPEG so anything that ignores
 * srcset/`<picture>` still gets a correct (if larger) image.
 *
 * `sizes` is picked per-image from the nearest layout wrapper class found in
 * the surrounding markup (see WRAPPER_RULES) — this file's HTML structure is
 * consistent enough (one wrapper class immediately around each `.media`) that
 * a text-proximity match is reliable without a real DOM parser.
 *
 * Idempotent: running twice is a no-op on the second run, since by then the
 * `<img>` tags are already nested in `<picture>` and no longer match the
 * bare-`<img src="/assets/images/*.jpg">` pattern this script looks for
 * outside of a `<picture>` (checked explicitly, see isAlreadyPicture).
 */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = join(import.meta.dirname, '..');
const IMAGES_DIR = join(ROOT, 'public', 'assets', 'images');
const manifest = JSON.parse(readFileSync(join(IMAGES_DIR, 'responsive-manifest.json'), 'utf8'));

const HTML_FILES = [
  ...readdirSync(ROOT).filter((f) => f.endsWith('.html')).map((f) => join(ROOT, f)),
  ...readdirSync(join(ROOT, 'src', 'partials')).filter((f) => f.endsWith('.html')).map((f) => join(ROOT, 'src', 'partials', f)),
];

function classOf(tag) {
  const m = tag.match(/class="([^"]*)"/);
  return m ? m[1] : '';
}

function enclosingMediaClass(content, imgIndex) {
  const openIdx = content.lastIndexOf('<div class="media', imgIndex);
  if (openIdx === -1) return '';
  const tagEnd = content.indexOf('>', openIdx);
  return classOf(content.slice(openIdx, tagEnd));
}

function isInsideWideCaseGrid(content, imgIndex) {
  const openIdx = content.lastIndexOf('<div class="case-grid', imgIndex);
  if (openIdx === -1) return false;
  const tagEnd = content.indexOf('>', openIdx);
  return content.slice(openIdx, tagEnd).includes('--wide');
}

function sizesFor(content, imgIndex, mediaClass) {
  if (mediaClass.includes('page-hero__media')) return '100vw';
  if (mediaClass.includes('hero__fallback')) return '100vw';

  const window = content.slice(Math.max(0, imgIndex - 500), imgIndex);
  if (/class="lifestyle-banner/.test(window)) return '100vw';
  if (window.includes('feature-row__media')) return '(max-width: 900px) 100vw, 45vw';
  if (window.includes('split__media')) return '(max-width: 900px) 100vw, 50vw';
  if (window.includes('well-compare__media')) return '(max-width: 900px) 100vw, 38vw';
  if (window.includes('safety-intro__media')) return '(max-width: 1080px) 100vw, 43vw';
  if (window.includes('cabin-card__btn')) return '(max-width: 1080px) 50vw, 33vw';
  if (window.includes('solution-card')) return '(max-width: 1080px) 50vw, 25vw';
  if (window.includes('details-card')) return '(max-width: 900px) 100vw, (max-width: 1080px) 50vw, 33vw';
  if (window.includes('case-tile')) {
    return isInsideWideCaseGrid(content, imgIndex)
      ? '(max-width: 640px) 100vw, (max-width: 1080px) 50vw, 33vw'
      : '(max-width: 640px) 50vw, (max-width: 1080px) 33vw, 20vw';
  }
  console.warn(`  ! no wrapper rule matched near index ${imgIndex} — using generic fallback sizes`);
  return '(max-width: 900px) 100vw, 50vw';
}

const IMG_RE = /<img src="\/assets\/images\/([\w-]+)\.jpg"([^>]*)>/g;

function isAlreadyPicture(content, imgIndex) {
  // If this <img> is already the fallback inside a <picture> we built, the
  // nearest preceding "<picture" is closer than the nearest preceding "</picture>".
  const p = content.lastIndexOf('<picture', imgIndex);
  const closeP = content.lastIndexOf('</picture>', imgIndex);
  return p !== -1 && p > closeP;
}

// The WebP <source> carries the srcset; the <img> is just the original JPEG as
// a fallback for anything that can't decode WebP.
function buildPicture(base, attrs, sizes) {
  const entry = manifest[base];
  if (entry.singleWebp) {
    return `<picture><source type="image/webp" srcset="/assets/images/${entry.singleWebp}"><img src="/assets/images/${base}.jpg"${attrs}></picture>`;
  }
  const srcset = entry.variants.map((v) => `/assets/images/${v.webp} ${v.width}w`).join(', ');
  return `<picture><source type="image/webp" srcset="${srcset}" sizes="${sizes}"><img src="/assets/images/${base}.jpg"${attrs}></picture>`;
}

// Existing <picture> blocks from an earlier run: rebuild their srcset from the
// current manifest (tiers may have changed), keeping the sizes already chosen.
const PICTURE_RE = /<picture><source type="image\/webp" srcset="[^"]*"(?: sizes="([^"]*)")?><img src="\/assets\/images\/([\w-]+)\.jpg"(?: srcset="[^"]*")?(?: sizes="[^"]*")?([^>]*)><\/picture>/g;

let totalConverted = 0;
let totalRefreshed = 0;

for (const file of HTML_FILES) {
  const original = readFileSync(file, 'utf8');
  let converted = 0;
  let refreshed = 0;

  let content = original.replace(PICTURE_RE, (full, sizes, base, attrs, offset, fullString) => {
    if (!manifest[base]) return full;
    refreshed++;
    const needsSizes = !manifest[base].singleWebp && !sizes;
    return buildPicture(base, attrs, needsSizes ? sizesFor(fullString, offset, enclosingMediaClass(fullString, offset)) : sizes);
  });

  content = content.replace(IMG_RE, (full, base, attrs, offset, fullString) => {
    if (isAlreadyPicture(fullString, offset)) return full;
    if (!manifest[base]) {
      console.warn(`  ! ${file}: no manifest entry for "${base}.jpg" — left as plain <img>`);
      return full;
    }
    converted++;
    return buildPicture(base, attrs, sizesFor(fullString, offset, enclosingMediaClass(fullString, offset)));
  });

  if (content !== original) {
    writeFileSync(file, content);
    console.log(`${file.replace(ROOT + '/', '')}: converted ${converted}, refreshed ${refreshed}`);
  }
  totalConverted += converted;
  totalRefreshed += refreshed;
}

console.log(`\nTotal converted: ${totalConverted}, refreshed: ${totalRefreshed}`);
